import { constants as fsConstants } from "node:fs";
import { access } from "node:fs/promises";
import { createRequire } from "node:module";
import { platform } from "node:os";
import { join } from "node:path";
import { type Logger, noopLogger } from "../common/types/logger";

interface MacPermissions {
    hasInputMonitoringPermission(): boolean;
}

/**
 * Checks whether the current process has OS-level permission to communicate
 * with Work Louder HID devices.
 *
 * Platform behaviour:
 *
 * | Platform | Mechanism |
 * |----------|-----------|
 * | **macOS** | Checks Input Monitoring authorization via the bundled native addon. |
 * | **Linux** | Probes read/write access on the supplied HID device node paths. |
 * | **Windows / other** | Always returns `true` (no OS gate). |
 *
 * @example
 * ```ts
 * const discovery = new WLDeviceDiscovery();
 * const permissions = new WLPermissions();
 * const devices = discovery.findWLDevices();
 * const allowed = await permissions.check(devices.map(d => d.portPath));
 * ```
 */
class WLPermissions {
    private log: Logger;

    constructor(logger?: Logger) {
        this.log = logger ?? noopLogger;
    }

    /**
     * Returns `true` when the current process is allowed to open Work Louder
     * HID devices, `false` otherwise.
     *
     * @param devicePaths - OS-level HID device node paths (e.g. from
     *   {@link WLDevice.portPath}). Required on Linux; ignored on other
     *   platforms.
     */
    public async check(devicePaths: string[] = []): Promise<boolean> {
        switch (platform()) {
            case "darwin":
                return this.hasDarwinPermissions();
            case "linux":
                return this.hasLinuxPermissions(devicePaths);
            default:
                return true;
        }
    }

    private async hasDarwinPermissions(): Promise<boolean> {
        try {
            const require = createRequire(__filename);
            const permissions = require(
                join(__dirname, "native", "darwin", "permissions.node")
            ) as MacPermissions;

            return permissions.hasInputMonitoringPermission();
        } catch (error) {
            this.log.error("Failed to load the macOS permissions addon.", error);
            return false;
        }
    }

    /**
     * Verifies read/write access to the supplied HID device nodes.
     * Returns `true` when the list is empty (nothing to verify).
     */
    private async hasLinuxPermissions(devicePaths: string[]): Promise<boolean> {
        const uniquePaths = [...new Set(devicePaths)];

        if (uniquePaths.length === 0) {
            this.log.debug("No HID device paths supplied for Linux permission check; returning true.");
            return true;
        }

        const accessMode = fsConstants.R_OK | fsConstants.W_OK;

        for (const devicePath of uniquePaths) {
            try {
                await access(devicePath, accessMode);
            } catch {
                this.log.warn(`Linux HID permission check failed for device path: ${devicePath}`);
                return false;
            }
        }

        return true;
    }
}

export default WLPermissions;
