import * as nodeHID from "node-hid";
import { SerialPort } from "serialport";
import { ConnectionType } from "../common/types/connection_type";
import { DEVICE_REGISTRY } from "./const/device_registry";
import { DeviceType } from "../common/types/device_type";
import { DeviceLayoutType } from "../common/types/device_layout_type";
import { WLDevice } from "../common/types/wl_device";
import { type Logger, noopLogger } from "../common/types/logger";
import { prefixLogger } from "../utils/logger_utils";
import { WL_VID, WL_MANUFACTURER } from "./const/wl_const";


/**
 * Enumerates connected Work Louder hardware by scanning USB HID and serial
 * ports. This is the primary entry point for discovering devices before
 * connecting to them via {@link WLDeviceComm}.
 *
 * Typical usage:
 * ```ts
 * const discovery = new WLDeviceDiscovery();
 * const devices = discovery.findWLDevices();
 * const bootloaders = await discovery.findWLBootloaderDevices();
 * ```
 */
class WLDeviceDiscovery {
    private log: Logger;

    /**
     * @param logger - Optional {@link Logger} instance. If omitted, logging is disabled.
     */
    constructor(logger?: Logger) {
        this.log = prefixLogger(logger ?? noopLogger, "wl_device_discovery");
    }

    /**
     * Synchronously scans all connected USB HID devices and returns those
     * that match known Work Louder Product IDs on the vendor-specific HID
     * usage page (`0xFF00`).
     *
     * @param filter - When provided, only devices whose {@link WLDevice.deviceType}
     *   is in this array are returned. Pass `undefined` or omit to get all devices.
     * @returns An array of discovered {@link WLDevice} descriptors (may be empty).
     */
    public findWLDevices(filter?: DeviceType[]): WLDevice[] {
        const hidDevices = nodeHID.devices();

        // First try with manufacturer check
        const wlDevices = this.filterWLDevices(hidDevices);

        // If no filter is passed we return everything
        if (!filter) {
            return wlDevices;
        }

        return wlDevices.filter((device) => filter.includes(device.deviceType));
    }

    /**
     * Filters raw HID device descriptors down to recognized Work Louder
     * devices. First attempts matching by manufacturer string + VID; falls
     * back to VID-only if no manufacturer match is found.
     */
    private filterWLDevices(hidDevices: nodeHID.Device[]): WLDevice[] {
        // First try with manufacturer check
        let workLouderDevices = hidDevices.filter(device =>
            device.manufacturer !== undefined &&
            WL_MANUFACTURER.some(manufacturer =>
                device.manufacturer!.includes(manufacturer)
            ) &&
            device.vendorId === WL_VID
        );

        // If no devices found with manufacturer check, try without manufacturer check
        if (workLouderDevices.length === 0) {
            workLouderDevices = hidDevices.filter(device =>
                device.vendorId === WL_VID
            );
        }

        return workLouderDevices.map((device) => {
            if (!device.path || !device.productId || device.usagePage !== 0xFF00) {
                return;
            }

            const wlDevice = DEVICE_REGISTRY.get(device.productId)

            if (!wlDevice) {
                return;
            }

            const isUsb = (device.release & 0x0003) === 0x00;

            return {
                portPath: device.path,
                devicePid: device.productId.toString(),
                connectionType: ConnectionType.hid,
                deviceType: wlDevice.type,
                layoutType: wlDevice.layout,
                isUsbConnection: isUsb,
            }
        }).filter((device) => device !== undefined);
    }

    /**
     * Asynchronously scans serial ports for Work Louder devices in bootloader
     * (DFU) mode. Bootloader devices appear as serial ports with the
     * Espressif manufacturer string or (on Windows) a serial number ending
     * in `"0000"`.
     *
     * @returns An array of discovered bootloader {@link WLDevice} descriptors (may be empty).
     */
    public async findWLBootloaderDevices(): Promise<WLDevice[]> {
        const serialDevices = await SerialPort.list();
        return this.filterBootloaderDevices(serialDevices);
    }

    /**
     * Filters serial port descriptors to find Work Louder bootloader devices.
     * Uses platform-specific heuristics: on Windows, matches serial numbers
     * ending in `"0000"`; on other platforms, matches the `"Espressif"` manufacturer.
     */
    private filterBootloaderDevices(serialPorts: any[]): WLDevice[] {
        const isWin = (process.platform === "win32");
        try {
            let bootloaderDevices: WLDevice[] = [];
            serialPorts.forEach((port) => {
                const vendorId = parseInt(port.vendorId ?? '', 16);
                if (isNaN(vendorId) || vendorId !== WL_VID) {
                    return;
                }

                const parsedProductId = parseInt(port.productId, 16);
                const productId = isNaN(parsedProductId) ? "0" : parsedProductId.toString();
                const device = {
                    portPath: port.path,
                    devicePid: productId,
                    connectionType: ConnectionType.serial,
                    deviceType: DeviceType.Bootloader,
                    layoutType: DeviceLayoutType.unknown,
                    isUsbConnection: true,
                }

                if (isWin && port.serialNumber?.endsWith("0000")) {
                    bootloaderDevices.push(device);
                } else if (port.manufacturer === "Espressif") {
                    bootloaderDevices.push(device);
                }
            });

            return bootloaderDevices;
        } catch (error) {
            this.log.error(error)
            return [];
        }
    }
}

export default WLDeviceDiscovery;