/**
 * Enumeration of error codes thrown by the Work Louder device kit.
 * Use these codes in `catch` blocks to programmatically distinguish
 * error conditions instead of matching against error message strings.
 *
 * @example
 * ```ts
 * try {
 *   await comm.connect(device);
 * } catch (err) {
 *   if (err instanceof WLDeviceError && err.code === WLDeviceErrorCode.AlreadyConnected) {
 *     // handle gracefully
 *   }
 * }
 * ```
 */
export enum WLDeviceErrorCode {
    /** A connection attempt was made while a device is already connected. */
    AlreadyConnected = "ALREADY_CONNECTED",
    /** A request was sent but no response arrived within the timeout window. */
    Timeout = "TIMEOUT",
    /** Data could not be written to the device transport. */
    WriteFailed = "WRITE_FAILED",
    /** The device disconnected while a request was in-flight or pending. */
    DeviceDisconnected = "DEVICE_DISCONNECTED",
}

/**
 * Typed error thrown by {@link WLDeviceCommImpl} for known device-level
 * failure conditions. Always carries a {@link WLDeviceErrorCode} so callers
 * can branch on the error type without string-matching `.message`.
 */
export class WLDeviceError extends Error {
    public readonly code: WLDeviceErrorCode;

    constructor(code: WLDeviceErrorCode, message?: string) {
        super(message ?? code);
        this.name = "WLDeviceError";
        this.code = code;
    }
}
