/**
 * String constants for every JSON-RPC method supported by Work Louder
 * device firmware. Used internally by {@link WLRPCApi} to construct requests.
 */
export enum JsonRPCMethods {
    // Legacy (pre-`sys.*`) RPC calls.
    /** Legacy: query firmware version. */
    VersionLegacy = "version",
    /** Legacy: reboot into bootloader. */
    BootloaderLegacy = "bootloader",
    /** Legacy: enter self-test mode. */
    SelftestLegacy = "selftest",

    // System.
    /** Query firmware version (JSON-RPC). */
    SysVersion = "sys.version",
    /** Reboot into bootloader (JSON-RPC). */
    SysBootloader = "sys.bootloader",
    /** Enter self-test / diagnostic mode. */
    SysSelftest = "sys.selftest",

    // Device.
    /** Query the full device status (firmware, profile, layer, battery). */
    DeviceStatus = "device.status",

    // Media playback / metadata.
    /** Send currently playing media metadata to the device display. */
    MpWriteInfo = "mp.write_info",
    /** Stream album artwork to the device display in base64 chunks. */
    MpWriteArtwork = "mp.write_artwork",

    // Filesystem.
    /** List all files on the device filesystem (with optional checksums). */
    FsList = "fs.list",
    /** Read an entire file from the device filesystem (JSON payload). */
    FsRead = "fs.read",
    /** Write an entire file to the device filesystem (JSON payload). */
    FsWrite = "fs.write",
    /** Write binary data to a file in base64-encoded chunks. */
    FsWriteBin = "fs.writebin",
    /** Read binary data from a file in base64-encoded chunks. */
    FsReadBin = "fs.readbin",
    /** Delete a file from the device filesystem. */
    FsDelete = "fs.delete",
    /** Start a filesystem transaction for writing multiple files atomically. */
    FsBegin = "fs.txbegin",
    /** Commit a filesystem transaction started with `fs.txbegin`. */
    FsCommit = "fs.txcommit",
    /** Delete a folder from the device filesystem. */
    FsDeleteDir = "fs.rmdir",

    // Firmware apps.
    /** List apps currently available in the firmware app carousel. */
    AppMgrListActive = "appmgr.list_active",
    /** List custom apps installed on the device. */
    AppMgrListInstalled = "appmgr.list_installed",

    // UI.
    /** Query the currently active screen on the device display. */
    UiActiveScreen = "ui.active_screen",
    /** Set the accent color shown on the device home screen. */
    UiHomeAccentColor = "ui.home_accent_color",

    // Lighting / host.
    /** Send a real-time lighting preview configuration. */
    LightsPreview = "lights.preview",
    /** Notify the device about the currently focused desktop application. */
    HostFocusedApp = "host.focused_app",
}

/**
 * High-level API for interacting with Work Louder device firmware over
 * JSON-RPC 2.0 (and legacy `#rpc#` protocol where needed).
 *
 * Built on top of {@link WLDeviceComm} (transport) and {@link WLRPCClient}
 * (request framing), this class exposes typed methods for every firmware
 * capability: system commands, device status, filesystem operations,
 * media playback metadata, lighting control, and UI customisation.
 *
 * Instantiate with an already-created {@link WLDeviceComm} instance
 * (connection does not need to be open yet):
 *
 * ```ts
 * const comm = new WLDeviceCommImpl(logger);
 * const api  = new WLRPCApi(comm, logger);
 *
 * await comm.connect(device);
 * const status = await api.getDeviceStatus();
 * ```
 */
class WLRPCApi {
    /** Maximum number of base64 characters allowed per chunk on the wire. */
    private static readonly MAX_CHUNK_BASE64_SIZE = 4096;
    /**
     * Raw byte count that base64-encodes to exactly {@link MAX_CHUNK_BASE64_SIZE} characters.
     * Since base64 encodes every 3 bytes into 4 characters: floor(4096 / 4) * 3 = 3072.
     */
    private static readonly CHUNK_RAW_BYTE_SIZE = Math.floor(WLRPCApi.MAX_CHUNK_BASE64_SIZE / 4) * 3; // 3072

    private deviceComm: WLDeviceComm;
    private rpcController: EventEmitter<RpcSignal> = new EventEmitter();
    private rpcClient: WLRPCClient;
    private log: Logger;

    /**
     * @param device - The {@link WLDeviceComm} transport to send requests through.
     * @param logger - Optional {@link Logger} instance. If omitted, logging is disabled.
     */
    constructor(device: WLDeviceComm, logger?: Logger) {
        this.deviceComm = device;
        this.rpcClient = new WLRPCClient(device, logger);
        this.log = prefixLogger(logger ?? noopLogger, "wl_rpc_api");
    }

    /**
     * Returns the underlying {@link WLRPCClient} used for all requests on this API instance.
     *
     * Prefer the typed methods on {@link WLRPCApi} when available. Use this when you need
     * {@link WLRPCClient.sendRpcCall} or {@link WLRPCClient.sendLegacyRpcRequest} directly
     * (e.g. custom or experimental firmware methods not yet wrapped here).
     *
     * @returns The same client constructed in the constructor; shares transport and logger with this API.
     */
    public getRpcClient(): WLRPCClient {
        return this.rpcClient;
    }

    /**
     * Signals an in-progress or queued RPC operation to abort.
     * Pending chunks for chunked writes are removed from the send queue.
     *
     * @param rpcId - The controller id returned by the `controller` callback
     *   in {@link writeFileChunkedFromStr}.
     */
    public abortRpcCall(rpcId: string) {
        this.log.info("Received abort from rpcId:", rpcId);
        this.rpcController.emit({ rpcId: rpcId, signal: RpcSignalType.abort });
    }

    /**
     * Queries the firmware version using the legacy `#version#` text protocol.
     * @returns The firmware version string reported by the device.
     */
    public async getFirmwareVersionLegacy(): Promise<string> {
        return this.rpcClient.sendLegacyRpcRequest(JsonRPCMethods.VersionLegacy);
    }

    /**
     * Queries the firmware version via JSON-RPC (`sys.version`).
     * @returns The firmware version string reported by the device.
     * @throws If the RPC call fails or the device returns an error.
     */
    public async getFirmwareVersion(): Promise<string> {
        try {
            const response = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.SysVersion });
            return response.result.version;
        } catch (error) {
            this.log.error(error);
            throw error;
        }
    }

    /**
     * Retrieves the current device status including firmware version,
     * active profile/layer indices, battery level, and charging state.
     *
     * @returns A validated {@link WLDeviceStatus} snapshot.
     * @throws If the RPC call fails or the response contains invalid data types.
     */
    public async getDeviceStatus(): Promise<WLDeviceStatus> {
        try {
            const response = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.DeviceStatus });
            const result = response.result;
            const firmwareVersion = result.version;
            const selectedProfileIndex = result.profile_index;
            const selectedLayerIndex = result.layer_index;
            const batteryPercentage = result.battery;
            const isCharging = result.is_charging;

            if ((firmwareVersion === undefined || typeof firmwareVersion === "string") &&
                (selectedProfileIndex === undefined || typeof selectedProfileIndex === "number") &&
                (selectedLayerIndex === undefined || typeof selectedLayerIndex === "number") &&
                (batteryPercentage === undefined || typeof batteryPercentage === "number") &&
                (isCharging === undefined || typeof isCharging === "boolean")) {
                return {
                    firmwareVersion,
                    selectedProfileIndex,
                    selectedLayerIndex,
                    batteryPercentage,
                    isCharging,
                } satisfies WLDeviceStatus;
            }
            this.log.info("Data type is invalid");
            throw Error("Data type is invalid");
        } catch (error) {
            this.log.error(error);
            throw error;
        }
    }

    /**
     * Reboots the device into bootloader (DFU) mode using the legacy
     * `#bootloader#` text protocol. The device will disconnect after this call.
     */
    public async sendIntoBootloaderLegacy(): Promise<void> {
        return this.rpcClient.sendLegacyRpcRequest(JsonRPCMethods.BootloaderLegacy);
    }

    /**
     * Reboots the device into bootloader (DFU) mode via JSON-RPC
     * (`sys.bootloader`). The device will disconnect after this call.
     * @throws If the RPC call fails.
     */
    public async sendIntoBootloader(): Promise<void> {
        try {
            const response = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.SysBootloader });
            return response.result;
        } catch (error) {
            this.log.error(error);
            throw error;
        }
    }

    /**
     * Enters self-test / diagnostic mode using the legacy `#selftest#` text protocol.
     */
    public async sendIntoSelfTestLegacy(): Promise<void> {
        return this.rpcClient.sendLegacyRpcRequest(JsonRPCMethods.SelftestLegacy);
    }

    /**
     * Enters self-test / diagnostic mode via JSON-RPC (`sys.selftest`).
     * @throws If the RPC call fails.
     */
    public async sendIntoSelfTest(): Promise<void> {
        try {
            const response = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.SysSelftest });
            return response.result
        } catch (error) {
            this.log.error(error);
            throw error;
        }
    }

    /**
     * Sends currently playing media metadata to the device display.
     *
     * @param params - Media playback information.
     * @param params.song_title - Title of the currently playing track.
     * @param params.artist - Artist name.
     * @param params.duration - Total track duration in seconds.
     * @param params.elapsed - Elapsed playback time in seconds.
     * @param params.isPlaying - `true` if playback is active.
     * @returns `true` if the device acknowledged the data, `false` on error.
     */
    public async sendMediaInfo({ song_title, artist, duration, elapsed, isPlaying }: { song_title?: string, artist?: string, duration?: number, elapsed?: number, isPlaying?: boolean }): Promise<boolean> {
        try {
            await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.MpWriteInfo, params: { song_title: song_title, artist: artist, elapsed: elapsed, total_duration: duration, is_playing: isPlaying } })
            return true;
        } catch (error) {
            this.log.error(error);
            return false;
        }
    }

    /**
     * Lists files on the device filesystem, including size and checksum.
     *
     * @param options - Optional filesystem listing controls.
     * @param options.path - Directory or file path to list. Omit to list the default root.
     * @param options.recursive - `true` to include nested files.
     * @returns An array of {@link WLDeviceFileSummary} objects, or an empty array on error.
     */
    public async getFileList(options?: { path?: string, recursive?: boolean }): Promise<WLDeviceFileSummary[]> {
        try {
            const result = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.FsList, params: { checksum: true, rec: options?.recursive, path: options?.path } });
            const fileList = result.result.map((element: any): WLDeviceFileSummary => ({
                name: element.name,
                size: element.size,
                checksum: element.checksum,
            }));
            return fileList;
        } catch (error) {
            this.log.error("Error while getting file list", error);
            return [];
        }
    }

    /**
     * Reads an entire file from the device filesystem as a JSON payload.
     * Suitable for small files; for large binary files use {@link readFileChunked}.
     *
     * @param fileName - The filename on the device to read.
     * @returns The file contents (parsed JSON), or `undefined` if the file does not exist.
     * @throws {Error} If the device returns any error other than "File does not exist".
     */
    public async readFile(fileName: string): Promise<any | undefined> {
        try {
            const result = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.FsRead, params: { file: fileName } })
            return result.result;
        } catch (error: any) {
            if (error.message === "File does not exist") {
                return undefined;
            }
            this.log.error(error);
            throw error;
        }
    }

    /**
     * Writes an entire file to the device filesystem as a JSON payload.
     * Suitable for small files; for large binary files use {@link writeFileChunked}.
     *
     * @param fileName - The target filename on the device.
     * @param data - The file contents to write (will be serialized as the `data` field).
     * @returns The device's acknowledgment result, or `undefined` on error.
     */
    public async writeFile(fileName: string, data: any): Promise<any | undefined> {
        try {
            const result = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.FsWrite, params: { file: fileName, data: data } });
            return result.result;
        } catch (error) {
            this.log.error("Error while writing file", error);
            return;
        }
    }

    /**
     * Writes a string to the device filesystem by encoding it into base64
     * chunks. Each request carries at most 4096 base64 characters.
     *
     * Supports cooperative cancellation: the `controller` callback receives a
     * UUID that can later be passed to {@link abortRpcCall} to cancel
     * remaining chunks.
     *
     * @param fileName - The target filename on the device.
     * @param inputString - The UTF-8 string data to write.
     * @param controller - Called immediately with a cancellation id (`rpcId`).
     *   Store this id and pass it to {@link abortRpcCall} to cancel the write.
     * @returns `true` if the entire file was written successfully, `false` on error or abort.
     */
    async writeFileChunkedFromStr(fileName: string, inputString: string, controller: (rpcId: string) => void): Promise<boolean> {
        const uuid = crypto.randomUUID();
        controller(uuid);

        let chunkedRpcCalls: { id: number, promise: Promise<JsonRpcResponse> }[] = [];
        let operationCompleted = false;

        const unsubController = this.rpcController.on((rpcSignal) => {
            if (operationCompleted || rpcSignal.rpcId !== uuid || rpcSignal.signal !== RpcSignalType.abort) {
                return;
            }
            operationCompleted = true;
            unsubController?.();

            chunkedRpcCalls.forEach((promise) => {
                this.log.info("Aborted RPC call, id:", promise.id);
                this.deviceComm.abortJsonRpcRequest(promise.id.toString());
            });
            return false;
        });

        try {
            const encoder = new TextEncoder();
            const data = encoder.encode(inputString);
            const chunkSize = WLRPCApi.CHUNK_RAW_BYTE_SIZE;
            const chunks = this.splitIntoBase64Chunks(data, chunkSize);
            // We send all the chunks so that they can get put into queue
            chunks.forEach((chunk, index) => {
                const id = this.rpcClient.createRpcId();
                chunkedRpcCalls.push({
                    id: id,
                    promise: this.rpcClient.sendRpcCall({
                        method: JsonRPCMethods.FsWriteBin,
                        params: {
                            file: fileName,
                            data: chunk,
                            append: true,
                            completed: index === chunks.length - 1,
                            offset: chunkSize * index
                        },
                        id: id
                    })
                });
            });

            // Then we await them for the result
            for (let index = 0; index < chunkedRpcCalls.length; index++) {
                // If we abort we get out immediately
                if (operationCompleted) {
                    break;
                }
                const rpcCall = chunkedRpcCalls[index];
                const result = await rpcCall.promise;
                this.log.debug(result);
            }

            operationCompleted = true;
            unsubController?.();
            return true;
        } catch (error) {
            this.log.error("Error while writing chunked data", error);
            return false;
        } finally {
            operationCompleted = true;
            unsubController?.();
        }
    }

    /**
     * Writes binary data to a file on the device filesystem via `fs.writebin`.
     * Data is split into raw chunks that encode to at most 4096 base64
     * characters. All chunks are enqueued upfront and awaited sequentially.
     *
     * @param fileName - The target filename on the device.
     * @param data - The raw binary data to write.
     * @param transactionId - Optional transaction id returned by {@link beginMultifileWrite}.
     * @returns `true` on success, `false` on error, or `undefined` on unexpected failure.
     */
    async writeFileChunked(fileName: string, data: Uint8Array, transactionId?: string): Promise<boolean | undefined> {
        try {
            const chunkSize = WLRPCApi.CHUNK_RAW_BYTE_SIZE;
            let chunks = this.splitIntoBase64Chunks(data, chunkSize);
            // We send all the chunks so that they can get put into queue
            const promises = chunks.map((chunk, index) => this.rpcClient.sendRpcCall({
                method: JsonRPCMethods.FsWriteBin,
                params: {
                    file: fileName,
                    data: chunk,
                    append: true,
                    completed: index === chunks.length - 1,
                    offset: chunkSize * index,
                    tx: transactionId
                }
            }));

            // Then we await them for the result
            for (let index = 0; index < promises.length; index++) {
                const promise = promises[index];
                const result = await promise;
                this.log.debug(result);
            }
            return true;
        } catch (error) {
            this.log.error("Error while writing chunked data", error);
            return false;
        }
    }

    /**
     * Reads a binary file from the device filesystem via `fs.readbin`.
     * Requests are sized so each base64 response stays within the firmware
     * payload limit.
     *
     * @param fileName - The filename on the device to read.
     * @returns The full file as a {@link Buffer}, or `undefined` on error.
     */
    async readFileChunked(fileName: string): Promise<Buffer | undefined> {
        try {
            let offset = 0;
            let fileSize = 0;
            const chunkBuffers: Buffer[] = [];
            let chunkSize = WLRPCApi.CHUNK_RAW_BYTE_SIZE;
            do {
                const chunk = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.FsReadBin, params: { file: fileName, offset: offset, len: chunkSize } });
                this.log.info("Read chunk response");
                fileSize = chunk.result.total_size as number;
                const rawB64 = chunk.result.data as string;
                const decoded = Buffer.from(rawB64, "base64");
                if (decoded.length === 0 && offset < fileSize) {
                    this.log.error("readFileChunked: empty chunk before end of file");
                    return;
                }
                chunkBuffers.push(decoded);
                offset += decoded.length;
                const remaining = fileSize - offset;
                if (remaining < chunkSize) {
                    chunkSize = remaining;
                }
                await new Promise((resolve) => setTimeout(resolve, 50));
            } while (offset < fileSize);
            return Buffer.concat(chunkBuffers);
        } catch (error) {
            this.log.error("Error while reading chunked file", error);
            return;
        }
    }

    /**
     * Deletes a folder and everything beneath it from the device filesystem.
     *
     * @param path - The path of the folder on the device to delete.
     * @returns `true` if the folder was deleted successfully, or `undefined` on error.
     */
    public async deleteFolder(path: string): Promise<boolean | undefined> {
        try {
            await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.FsDeleteDir, params: { path: path } });
            return true;
        } catch (error) {
            this.log.error("Error while trying to delete folder, error: ", error);
            return;
        }
    }

    /**
     * Deletes a file from the device filesystem.
     *
     * @param fileName - The filename on the device to delete.
     * @returns `true` if the file was deleted successfully, or `undefined` on error.
     */
    public async deleteFile(fileName: string): Promise<boolean | undefined> {
        try {
            await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.FsDelete, params: { file: fileName } });
            return true;
        } catch (error) {
            this.log.error("Error while trying to delete file", error);
            return;
        }
    }
    /**
     * Streams album artwork image data to the device display via
     * `mp.write_artwork`. Each chunk includes its
     * byte offset and the total image size so the device can reassemble.
     *
     * @param data - Raw image data (e.g. JPEG or PNG bytes).
     * @returns `true` if all chunks were sent successfully, `false` on error.
     */
    public async writeMediaArtwork(data: Uint8Array): Promise<boolean> {
        try {
            const chunkSize = WLRPCApi.CHUNK_RAW_BYTE_SIZE;
            const chunks = this.splitIntoBase64Chunks(data, chunkSize);

            for (let index = 0; index < chunks.length; index++) {
                const chunk = chunks[index];
                const response = await this.rpcClient.sendRpcCall({
                    method: JsonRPCMethods.MpWriteArtwork,
                    params: {
                        data: chunk,
                        offset: index * chunkSize,
                        size: data.length
                    }
                });
                if (!response) {
                    return false;
                }
                await new Promise((resolve) => setTimeout(resolve, 50));
            }

            return true;
        } catch (error) {
            this.log.error("Error while writing chunked data", error);
            return false;
        }
    }

    /**
     * @deprecated Renamed to {@link writeMediaArtwork} (lowercase 'w').
     */
    public async writeMediaArtWork(data: Uint8Array): Promise<boolean> {
        return this.writeMediaArtwork(data);
    }

    /**
     * Queries the name of the screen currently displayed on the device.
     *
     * @returns The screen name string, or `undefined` on error.
     */
    public async getDeviceCurrentScreen(): Promise<string | undefined> {
        try {
            const response = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.UiActiveScreen });
            return response.result["screen_name"];
        } catch (error) {
            this.log.error(error);
            return undefined;
        }

    }

    /**
     * Sets the accent color displayed on the device's home screen.
     *
     * @param color - A color string (e.g. hex `"#FF5500"` or named color)
     *   accepted by the device firmware.
     */
    public async sendHomeAccentColor(color: string) {
        try {
            await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.UiHomeAccentColor, params: { color: color } });
        } catch (error) {
            this.log.error(error);
            return;
        }
    }

    /**
     * Sends a real-time lighting preview to the device. The preview is
     * applied immediately but is **not** persisted to flash storage.
     *
     * @param config - Backlight and underglow configuration to preview.
     */
    public async sendLightingPreview(config: WLDeviceLightingConfig) {
        try {
            await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.LightsPreview, params: config });
        } catch (error) {
            this.log.error(error)
            return;
        }
    }

    /**
     * Starts a filesystem transaction for writing several files as one group.
     *
     * Use this with {@link writeFileChunked} by passing the returned transaction
     * id, then finish with {@link commitMultifileWrite}. For the common case,
     * {@link sendMultipleFiles} wraps the whole flow.
     *
     * @returns The transaction id reported by the device, or `undefined` on error.
     */
    public async beginMultifileWrite(): Promise<string | undefined> {
        try {
            const response = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.FsBegin });
            return response.result["tx"];
        } catch (error) {
            this.log.error(error)
            return;
        }
    }

    /**
     * Commits a filesystem transaction started with {@link beginMultifileWrite}.
     *
     * @param transactionId - Transaction id returned by `fs.txbegin`.
     * @returns `true` if the device accepted the commit, `false` on error.
     */
    public async commitMultifileWrite(transactionId: string): Promise<boolean> {
        try {
            await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.FsCommit, params: { tx: transactionId } });
            return true
        } catch (error) {
            this.log.error(error)
            return false;
        }
    }

    /**
     * Returns the apps currently available in the firmware app carousel.
     *
     * The list can contain both native firmware apps and custom installed apps.
     *
     * @returns An array of {@link FwActiveApp} objects, or an empty array on error.
     */
    public async getFwActiveApps(): Promise<FwActiveApp[]> {
        try {
            const response = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.AppMgrListActive });
            return response.result.map((element: any) => {
                const activeApp: FwActiveApp = {
                    bundleId: element.bundle,
                    name: element.name,
                    native: element.native
                };
                return activeApp;
            });
        } catch (error) {
            this.log.error(error)
            return [];
        }
    }

    /**
     * Returns custom apps installed on the device firmware.
     *
     * @returns An array of {@link FwApp} objects, or an empty array on error.
     */
    public async getFwInstalledApps(): Promise<FwApp[]> {
        try {
            const response = await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.AppMgrListInstalled });
            return response.result.map((element: any) => {
                const activeApp: FwApp = {
                    bundleId: element.bundle,
                    name: element.name,
                };
                return activeApp;
            });
        } catch (error) {
            this.log.error(error)
            return [];
        }
    }

    /**
     * Writes several binary files inside one filesystem transaction.
     *
     * This is the preferred helper for deploying custom app bundles or other
     * multi-file payloads. The method starts a transaction, writes each file via
     * {@link writeFileChunked}, and commits the transaction after every write
     * succeeds.
     *
     * @param files - Files to write to the device filesystem.
     * @returns `true` when all files are written and committed, `false` on error.
     */
    public async sendMultipleFiles(files: WLDeviceFilePayload[]): Promise<boolean> {
        try {
            const transactionId = await this.beginMultifileWrite();
            if (!transactionId) {
                return false;
            }

            for (const element of files) {
                const result = await this.writeFileChunked(element.name, element.data, transactionId);
                if (!result) {
                    return false;
                }
            }
            const result = await this.commitMultifileWrite(transactionId);
            return result;
        } catch (error) {
            this.log.error(error);
            return false;
        }
    }

    /**
     * Notifies the device about the currently focused desktop application
     * so it can display context-aware UI or switch profiles.
     *
     * @param app - Information about the focused application.
     */
    public async sendFocusApp(app: AppInFocus) {
        try {
            await this.rpcClient.sendRpcCall({ method: JsonRPCMethods.HostFocusedApp, params: app });
        } catch (error) {
            this.log.error(error)
            return;
        }
    }

    /**
     * Splits a `Uint8Array` into base64-encoded strings, each representing
     * at most `chunkSize` raw bytes.
     *
     * @param data - The raw binary data to split.
     * @param chunkSize - Maximum number of raw bytes per chunk.
     * @returns An array of base64-encoded chunk strings.
     */
    private splitIntoBase64Chunks(data: Uint8Array, chunkSize: number) {
        let offset = 0;
        let chunks: string[] = [];
        while (offset < data.length) {
            let end = offset + chunkSize;
            if (end >= data.length) {
                end = data.length;
            }

            const subArray = data.subarray(offset, end);
            chunks.push(Buffer
                .from(subArray)
                .toString("base64"));
            offset = end;
        }
        return chunks;
    }
}

export default WLRPCApi;
