import { randomInt } from "node:crypto";
import { JsonRpcRequest } from "../common/types/json_rpc_request";
import { JsonRpcError, JsonRpcResponse } from "../common/types/json_rpc_response";
import { escapeUnicode } from "../utils/string_utils";
import WLDeviceComm from "../wl_device_comm/wl_device_comm";
import { type Logger, noopLogger } from "../common/types/logger";
import { prefixLogger } from "../utils/logger_utils";

/**
 * Low-level JSON-RPC 2.0 client that serializes requests, generates
 * randomized call IDs, escapes non-ASCII characters, and delegates
 * transport to a {@link WLDeviceComm} instance.
 *
 * Used internally by {@link WLRPCApi}; consumers should prefer the
 * higher-level API unless building custom RPC flows.
 */
class WLRPCClient {
    private device: WLDeviceComm;
    private log: Logger;

    /**
     * @param device - The {@link WLDeviceComm} transport to send requests through.
     * @param logger - Optional {@link Logger} instance. If omitted, logging is disabled.
     */
    constructor(device: WLDeviceComm, logger?: Logger) {
        this.device = device;
        this.log = prefixLogger(logger ?? noopLogger, "wl_rpc_client");
    }

    /**
     * Forwards a legacy `#rpc#args#` request to the device transport.
     *
     * @param rpc - The legacy RPC command name.
     * @param args - Optional argument string.
     * @returns The parsed response payload.
     */
    public async sendLegacyRpcRequest(rpc: string, args?: string | null): Promise<any> {
        return this.device.sendLegacyRpcRequest(rpc, args);
    }

    /**
     * Constructs a {@link JsonRpcRequest}, serializes it to JSON with
     * Unicode-escaped non-ASCII characters, sends it through the device
     * transport, and parses the JSON-RPC response.
     *
     * Uses a random call ID unless one is explicitly provided via `id`.
     *
     * @param method - The JSON-RPC method name (e.g. `"sys.version"`).
     * @param params - Optional parameters object for the method. Defaults to `null`.
     * @param id - Optional call ID. When omitted a random ID is generated
     *   via {@link createRpcId}.
     * @returns The parsed {@link JsonRpcResponse} on success.
     * @throws {Error} If the device responds with a {@link JsonRpcError}.
     */
    public async sendRpcCall({ method, params = null, id }: { method: string, params?: any, id?: number }): Promise<JsonRpcResponse> {
        const idCall = id ?? this.createRpcId();
        const jsonRpcMessage = this.createJsonRpcRequest(method, params, idCall);
        try {
            const jsonRpc = JSON.stringify(jsonRpcMessage);
            const escaped = escapeUnicode(jsonRpc);
            this.log.info("Sending RPC call, id:", idCall);
            this.log.debug(escaped);
            const result = await this.device.sendJsonRpcRequest(escaped, idCall.toString());
            const obj = JSON.parse(result);

            if (obj.error !== undefined) {
                const response = obj as JsonRpcError;
                throw Error(response.error.message);
            }

            this.log.info("Received answer, id:", idCall, "method:", method);
            this.log.info(result);

            const jsonRpcResponse = obj as JsonRpcResponse;
            return jsonRpcResponse;
        } catch (error) {
            this.log.error("Error calling RPC, id:", idCall, "method:", method, error);
            throw error;
        }
    }

    /**
     * Generates a random integer to use as a JSON-RPC call ID.
     * Useful for pre-generating an ID when the caller needs to track or
     * abort an in-flight request (e.g. chunked writes).
     *
     * The range [0, 999) is constrained by device firmware — IDs outside
     * this range are not accepted. Keeping IDs short also avoids inflating
     * RPC message size (longer IDs can push a message from one packet to two).
     * Collisions are not a concern in practice because only one request is
     * ever in-flight at a time via the transport's process queue.
     */
    public createRpcId() {
        return randomInt(0, 999);
    }

    /**
     * Builds a {@link JsonRpcRequest} object from the given method, params, and id.
     */
    private createJsonRpcRequest(method: string, params: any = null, id: number): JsonRpcRequest {
        return {
            method,
            params,
            id,
        };
    }
}

export default WLRPCClient;