import { GithubAsset } from "./github_asset";

/**
 * Parsed representation of a single GitHub release entry.
 */
export class GithubData {
    /** Human-readable release name. */
    name: string;
    /** Git tag associated with the release (used as the version). */
    tagName: string;
    /** Markdown body of the release (changelog). */
    body: string;
    /** Downloadable assets attached to this release. */
    assets: GithubAsset[];

    constructor(name: string, tagName: string, body: string, assets: GithubAsset[]) {
        this.name = name;
        this.tagName = tagName;
        this.body = body;
        this.assets = assets;
    }

    /**
     * Creates a {@link GithubData} from a raw GitHub API release JSON object.
     *
     * @param json - A single release object from the GitHub Releases API.
     * @returns The parsed release data.
     * @throws When required fields (`name`, `tag_name`, `assets`) are missing.
     */
    static fromJson(json: any): GithubData {
        if (!json.name || !json.tag_name || !json.assets) {
            throw new Error("GitHub release doesn't have necessary fields");
        }
        const assets = json.assets
            .map((e: any) => GithubAsset.fromJson(e))
            .filter((e: GithubAsset | undefined): e is GithubAsset => e !== undefined);
        return new GithubData(json.name, json.tag_name, json.body, assets);
    }
}
