import { SerialPort as NodeSerialPort } from "serialport";
import { type Logger, noopLogger } from "../common/types/logger";
import { NodeWebSOpenOptions, NodeWebSPortFlags, NodeWebSPortInfo } from "./types/node_webs_port_types";


/**
 * Web Serial API polyfill backed by `serialport`.
 *
 * Implements the subset of the W3C Web Serial `SerialPort` interface that
 * esptool-js's `Transport` actually consumes:
 *
 *   - open(options)
 *   - close()
 *   - readable  (ReadableStream<Uint8Array>)
 *   - writable  (WritableStream<Uint8Array>)
 *   - setSignals({ dataTerminalReady, requestToSend })
 *   - getInfo() -> { usbVendorId, usbProductId }
 *
 * Pass an instance of `NodeWebSerialPort` to `new Transport(port, ...)` with
 * a single `as unknown as SerialPort` cast and the rest of esptool-js will
 * work unchanged.
 */
class NodeWebSerialPort {
    private readonly tag = "|node_web_serial_port|";
    private port: NodeSerialPort | undefined = undefined;
    private dataListener: ((chunk: Buffer) => void) | undefined;
    private errorListener: ((err: Error) => void) | undefined;
    private closeListener: (() => void) | undefined;

    public readable: ReadableStream<Uint8Array> | undefined = undefined;
    private writable: WritableStream<Uint8Array> | undefined = undefined;

    private log: Logger;

    constructor(private readonly path: string, private readonly info: NodeWebSPortInfo, logger?: Logger) {
        this.log = logger ?? noopLogger;
    }

    public getInfo(): NodeWebSPortInfo {
        return { ...this.info };
    }

    // This opens the port and prepares all the needed streams for
    // reading and writing to it
    public async open(options: NodeWebSOpenOptions): Promise<void> {
        if (this.port) {
            this.log.error(`${this.tag} port is already open`);
            throw new Error("port is already open");
        }

        const port = new NodeSerialPort({
            path: this.path,
            baudRate: options.baudRate,
            dataBits: options.dataBits ?? 8,
            stopBits: options.stopBits ?? 1,
            parity: options.parity ?? "none",
            rtscts: options.flowControl === "hardware",
            autoOpen: false,
            // node-serialport keeps its own internal high-water mark; the Web
            // Serial `bufferSize` hint is informational and safely ignored.
        });

        // We wait for the port to open
        await new Promise<void>((resolve, reject) => {
            port.open((err) => {
                if (err) {
                    this.log.error(`${this.tag} error while opening the port, ${err}`);
                    return reject(err);
                }
                resolve();
            });
        });

        this.port = port;
        this.writable = this.makeWritable(port);
        this.readable = this.makeReadable(port);
        this.log.info(`${this.tag} port is open on path:${this.path}, and baud=${options.baudRate}`);
    }

    public async close(): Promise<void> {
        if (!this.port) {
            this.log.info(`${this.tag} port is already closed`);
            return;
        }

        if (this.dataListener) {
            this.port.off("data", this.dataListener);
        }
        if (this.errorListener) {
            this.port.off("error", this.errorListener);
        }
        if (this.closeListener) {
            this.port.off("close", this.closeListener);
        }

        this.dataListener = undefined;
        this.errorListener = undefined;
        this.closeListener = undefined;

        await this.closePort();
        this.port = undefined;
        this.readable = undefined;
        this.writable = undefined;
    }

    public async setSignals(signals: { dataTerminalReady?: boolean, requestToSend?: boolean }): Promise<void> {
        if (!this.port) {
            this.log.error(`${this.tag} cannot set signal, port is undefined`);
            throw new Error("port is undefined");
        }
        // We map the signals
        const flags: NodeWebSPortFlags = { dtr: signals.dataTerminalReady, rts: signals.requestToSend };

        return this.setPortFlags(flags);
    }

    private makeWritable(port: NodeSerialPort): WritableStream<Uint8Array> {
        return new WritableStream<Uint8Array>({
            write: (chunk) => this.writeToPort(port, chunk),
            close: () => Promise.resolve(),
            abort: () => Promise.resolve(),
        })
    }

    private makeReadable(port: NodeSerialPort): ReadableStream<Uint8Array> {
        return new ReadableStream<Uint8Array>(
            {
                start: (controller) => this.onStartReadableStream(port, controller),
                cancel: () => {
                    if (this.dataListener) {
                        port.off("data", this.dataListener);
                        this.dataListener = undefined;
                    }
                }
            }
        )
    }

    private async writeToPort(port: NodeSerialPort, chunk: Uint8Array<ArrayBufferLike>): Promise<void> {
        return new Promise<void>((resolve, reject) => {
            const buffer = Buffer.from(chunk.buffer, chunk.byteOffset, chunk.byteLength);
            const onWriteResult = (writeErr: Error | null | undefined) => {
                if (writeErr) {
                    this.log.error(`${this.tag} error while writing to port, error: ${writeErr}`);
                    return reject(writeErr);
                }

                const onDrainResult = (drainErr: Error | null | undefined) => {
                    if (drainErr) {
                        this.log.error(`${this.tag} error while draining port, error: ${drainErr}`);
                        return reject(drainErr);
                    }
                    resolve();
                }

                // Need to wait for the OS buffer to drain so that high-baud flash writes
                // don't outrun the kernel and produce timeouts
                port.drain(onDrainResult);
            }
            port.write(buffer, onWriteResult)
        });
    }

    private onStartReadableStream(port: NodeSerialPort, controller: ReadableStreamDefaultController<Uint8Array<ArrayBufferLike>>) {
        const onData = (chunk: Buffer) => {
            // We deep copy because Node could reuse the underlying buffer
            controller.enqueue(new Uint8Array(chunk));
        }

        const onError = (err: Error) => {
            this.log.error(`${this.tag} received error on readable stream`);
            controller.error(err)
        }

        const onClose = () => {
            this.log.info(`${this.tag} readable stream on close called`);
            controller.close();
        }

        port.on("data", onData);
        port.on("error", onError);
        port.on("close", onClose);
        this.dataListener = onData;
        this.errorListener = onError;
        this.closeListener = onClose;
    }

    private async closePort() {
        return new Promise<void>((resolve, reject) => {
            if (!this.port?.isOpen) {
                this.log.info(`${this.tag} port is already closed`);
                return resolve();
            }

            const onPortCloseResult = (closeErr: Error | null | undefined) => {
                if (closeErr) {
                    this.log.error(`${this.tag} error while closing the port`);
                    return reject(closeErr);
                }
                this.log.info(`${this.tag} closed port successfully`);
                resolve();
            }

            this.port.close(onPortCloseResult);
        });
    }

    private async setPortFlags(flags: NodeWebSPortFlags): Promise<void> {
        return new Promise((resolve, reject) => {
            if (!this.port) {
                return reject(`${this.tag} port is undefined`);
            }
            const onSetSignalResult = (setSignalErr: Error | null | undefined) => {
                if (setSignalErr) {
                    this.log.error(`${this.tag} error while setting port flags`);
                    return reject(setSignalErr);
                }
                resolve();
            }
            this.port.set(flags, onSetSignalResult);
        });
    }
}

export default NodeWebSerialPort;