/**
 * Signal types that can be sent to an in-progress or queued RPC operation.
 */
export enum RpcSignalType {
    /** Cancel the RPC call and remove it from the send queue. */
    abort,
}

/**
 * Payload emitted on the internal RPC controller event bus to signal
 * a control action (e.g. abort) for a specific RPC call.
 */
export interface RpcSignal {
    /** The identifier of the RPC operation to signal. */
    rpcId: string,
    /** The signal to deliver. */
    signal: RpcSignalType
}