import { type Logger } from "../common/types/logger";

/** Width of the longest tag in use: `|wl_device_programmer|` (22 chars). Update if a longer tag is added. */
const TAG_PAD = 22;

/**
 * Wraps a {@link Logger} so that every call automatically prepends `|tag|`
 * as the first argument, padded to {@link TAG_PAD} characters so log messages
 * from all modules align at the same column.
 *
 * @example
 * ```ts
 * this.log = prefixLogger(logger ?? noopLogger, "wl_rpc_api");
 * this.log.info("connected"); // logs: |wl_rpc_api|           connected
 * ```
 */
export function prefixLogger(log: Logger, tag: string): Logger {
    const prefix = `|${tag}|`.padEnd(TAG_PAD);
    return {
        info: (...args: any[]) => log.info(prefix, ...args),
        error: (...args: any[]) => log.error(prefix, ...args),
        debug: (...args: any[]) => log.debug(prefix, ...args),
        warn: (...args: any[]) => log.warn(prefix, ...args),
    };
}
