import { type Logger, noopLogger } from "../common/types/logger";
import { prefixLogger } from "../utils/logger_utils";
import type { SerialPort } from "serialport";
import NodeWebSerialPort from "./node_webserial_port";
import { WLDevice } from "../browser_safe";
import { WL_VID } from "../wl_device_discovery/const/wl_const";
import * as fs from "fs";

// We run via tsx so that esptool-js's lib/*.js can be loaded despite using
// extensionless relative imports (Node's strict ESM resolver rejects those;
// tsx's resolver behaves like TypeScript and adds the right extension).
import * as esptoolRuntime from "esptool-js";
import type {
    FlashOptions,
    IEspLoaderTerminal,
    LoaderOptions,
} from "esptool-js";
import { createHash } from "node:crypto";
import { FlashEntry } from "./types/flash_entry";
import { WLDeviceEfuses } from "./types/wl_device_efuses";

const DEFAULT_FLASH_BAUD = 921_600;
const DEFAULT_BAUD = 115_200;

export type WLDeviceProgrammerProps = {
    onProgress?: (fileIndex: number, written: number, total: number) => void;
    onWriteData?: (data: string) => void;
    onWriteLine?: (data: string) => void;
    clean?: () => void;
    logger?: Logger;
}

class WLDeviceProgrammer {
    private log: Logger;
    private terminal: IEspLoaderTerminal;
    private onProgress: (fileIndex: number, written: number, total: number) => void;

    constructor({ onWriteData, onWriteLine, clean, logger, onProgress }: WLDeviceProgrammerProps) {
        this.log = prefixLogger(logger ?? noopLogger, "wl_device_programmer");
        this.terminal = {
            clean: clean ?? (() => { }),
            writeLine: onWriteLine ?? (() => { }),
            write: onWriteData ?? (() => { })
        }
        this.onProgress = onProgress ?? (() => { });
    }

    public async flashDeviceFirmware(device: WLDevice, filePath: string): Promise<boolean> {
        return this.flashFiles(device, [{ address: 0, path: filePath }], DEFAULT_FLASH_BAUD);

    }

    private async flashFiles(device: WLDevice, flashFiles: FlashEntry[], flashBaud: number): Promise<boolean> {
        if (!flashFiles.length) {
            this.log.error("Flash requires at least a file");
            return false
        }

        const fileArray: FlashOptions["fileArray"] = [];

        for (const flashFile of flashFiles) {
            const fileData = await fs.promises.readFile(flashFile.path);
            const data = new Uint8Array(fileData);
            fileArray.push({ data, address: flashFile.address });
        }

        const result = await this.connectToDevice(device, flashBaud);
        if (!result) {
            return false;
        }

        const { loader, transport } = result;

        const log = this.log;
        const progressCb = this.onProgress;

        let isSuccess = false;
        try {
            const flashOptions: FlashOptions = {
                fileArray,
                flashMode: "keep",
                flashFreq: "keep",
                flashSize: "keep",
                eraseAll: false,
                compress: true,
                reportProgress(fileIndex, written, total) {
                    const percentage = ((written / total) * 100).toFixed(1);
                    log.info("Flash progress, file:", fileIndex + 1, "progress:", `${percentage}% (${written}/${total})`);
                    progressCb(fileIndex, written, total);
                },
                calculateMD5Hash(image) {
                    return createHash("md5").update(image).digest("hex");
                },
            }

            await loader.writeFlash(flashOptions);
            log.info("Flash ended");
            isSuccess = await this.resetDeviceAfterFlash({ loader, transport });
        } catch (error) {
            this.log.error("Error while flashing", error);
            isSuccess = false
        } finally {
            await transport.disconnect();
            return isSuccess;
        }
    }

    private async createLoader(device: WLDevice, baudrate: number) {
        const polyfilledPort = new NodeWebSerialPort(device.portPath, {
            usbVendorId: WL_VID,
            usbProductId: parseInt(device.devicePid),
        }, this.log) as unknown as SerialPort;

        const transport = new esptoolRuntime.Transport(polyfilledPort, false);

        const terminal = this.terminal;

        const loaderOptions: LoaderOptions = {
            transport,
            baudrate,
            terminal,
            debugLogging: true,
        }

        const loader = new esptoolRuntime.ESPLoader(loaderOptions);
        return { loader, transport };
    }

    /**
     * Reads the eFuse identity block from an ESP32-based
     * Work Louder device and returns the decoded product metadata.
     *
     * **Important:** The device must be in bootloader mode for this
     * call to succeed.
     * @param device - The {@link WLDevice} to read from. Must be in bootloader mode.
     * @returns The parsed eFuse metadata, or `undefined` if the chip does not
     *          expose an `EFUSE_BASE` address (unsupported chip).
     */
    public async readEfuses(device: WLDevice): Promise<WLDeviceEfuses | undefined> {
        const { loader, transport } = await this.createLoader(device, DEFAULT_BAUD);
        try {
            await loader.main();

            const chip = loader.chip as unknown as { CHIP_NAME?: string; EFUSE_BASE?: number };
            const efuseBase = chip.EFUSE_BASE;
            if (!efuseBase) {
                return;
            }
            const blk3Base = (efuseBase + 0x7c) >>> 0;
            const w6Addr = (blk3Base + 6 * 4) >>> 0;
            const w7Addr = (blk3Base + 7 * 4) >>> 0;
            const w6 = (await loader.readReg(w6Addr)) >>> 0;
            const w7 = (await loader.readReg(w7Addr)) >>> 0;

            const product = w6 & 0xff;
            const variant = (w6 >>> 8) & 0xff;
            const serialNumber = (((w7 & 0xffff) << 16) | ((w6 >>> 16) & 0xffff)) >>> 0;
            const vendor = (w7 >>> 16) & 0xff;
            const efuses: WLDeviceEfuses = {
                product: product.toString(16).padStart(2, "0"),
                variant: variant.toString(16).padStart(2, "0"),
                serialNumber: serialNumber.toString(16).padStart(8, "0"),
                vendor: vendor.toString(16).padStart(2, "0"),
            };
            this.log.info("eFuse fields, product:", efuses.product, "variant:", efuses.variant, "serial:", efuses.serialNumber, "vendor:", efuses.vendor);
            return efuses;
        } finally {
            await transport.disconnect();
        }
    }

    private async resetDeviceAfterFlash({ loader, transport }: {
        loader: esptoolRuntime.ESPLoader;
        transport: esptoolRuntime.Transport;
    }) {
        try {
            this.log.info("Resetting device");
            // Trigger ESP32 software reset via RTC_CNTL_OPTIONS0_REG before
            // toggling DTR to put the chip back into normal run mode.
            await loader?.writeReg(0x6000812C, 0x00000000);
            await new Promise((resolve) => setTimeout(resolve, 100));
            await transport.setDTR(false);
            await new Promise((resolve) => setTimeout(resolve, 100));
            await transport.setDTR(true);
            this.log.info("Reset done");
            return true;
        } catch (error) {
            this.log.error("Failed to reset device", error);
            return false;
        }
    }

    private async connectToDevice(device: WLDevice, flashBaud: number) {
        try {
            const { loader, transport } = await this.createLoader(device, flashBaud);
            const chip = await loader.main();
            this.log.info("Connected to chip:", chip);
            return { loader, transport };
        } catch (error) {
            this.log.error("Error connecting to device", error);
            return undefined;
        }
    }
}

export default WLDeviceProgrammer;