import { HIDAsync } from "node-hid";
import { DelimiterParser, SerialPort } from "serialport";
import EventEmitter from "../utils/event_emitter";
import WLDeviceComm from "./wl_device_comm";
import { ConnectionEvent } from "./types/connection_event";
import { ConnectionType } from "../common/types/connection_type";
import { ConnectionEventType } from "./types/connection_event_type";
import { WLDevice } from "../common/types/wl_device";
import { type Logger, noopLogger } from "../common/types/logger";
import { prefixLogger } from "../utils/logger_utils";
import { WLDeviceError, WLDeviceErrorCode } from "../common/types/wl_device_error";

/**
 * Concrete implementation of {@link WLDeviceComm} that communicates with
 * Work Louder devices over USB HID or serial (UART).
 *
 * All outgoing requests are serialized through an internal FIFO queue with a
 * 50 ms inter-request cooldown so the device firmware has time to process each
 * command before the next one arrives.
 *
 * HID packets follow a custom framing protocol:
 * - Byte 0: `0x06` (report ID)
 * - Byte 1: channel (`1` = debug log, `2` = RPC)
 * - Byte 2: payload length
 * - Bytes 3–63: payload (up to 61 bytes per packet; longer messages are split)
 *
 * @see {@link WLDeviceComm} for the interface contract.
 */
class WLDeviceCommImpl implements WLDeviceComm {
    private log: Logger;
    private connectionListener = new EventEmitter<ConnectionEvent>();
    private CHANNEL_DEBUG = 1;
    private CHANNEL_RPC = 2;
    private connectedDevice: HIDAsync | undefined = undefined;
    private port: SerialPort | undefined = undefined;
    private _responseResolvers: Map<string, ResolverEntry> = new Map();
    private _rpcResolver: Map<string, ResolverEntry> = new Map();
    private _notifyResolvers: Map<string, NotifyHandler> = new Map();
    private rpcResponse: string = "";
    private connectionType: ConnectionType | undefined = undefined;
    private queue: Task<any>[] = [];
    private pending = false;

    /**
     * @param logger - Optional {@link Logger} instance. If omitted, logging is disabled.
     */
    constructor(logger?: Logger) {
        this.log = prefixLogger(logger ?? noopLogger, "wl_device_comm");
    }

    private buffers: Record<number, string> = {
        [this.CHANNEL_DEBUG]: '',
        [this.CHANNEL_RPC]: ''
    };

    /** @inheritDoc */
    public onConnectionEvent(callback: (event: ConnectionEvent) => void): () => void {
        return this.connectionListener.on(callback);
    }

    /** @inheritDoc */
    async connect(device: WLDevice): Promise<boolean> {
        if (device.connectionType === ConnectionType.serial) {
            this.log.info("Connecting with serial");
            return this.connectWithSerial(device.portPath);
        } else {
            this.log.info("Connecting with HID");
            return this.connectWithHID(device.portPath);
        }
    }

    /**
     * Opens a serial port at the given path (115200 baud) and wires up
     * data/error/close handlers.
     */
    private async connectWithSerial(portPath: string): Promise<boolean> {
        if (this.port) {
            this.log.info("A device is already connected")
            return Promise.reject(new WLDeviceError(WLDeviceErrorCode.AlreadyConnected, "A device is already connected"));
        }

        let resolveCb: any = undefined;
        let promise = new Promise<boolean>((resolve, _reject) => {
            resolveCb = resolve;
        });

        let baudRate = 115200;

        const port = new SerialPort({ path: portPath, baudRate: baudRate, autoOpen: false });

        port.on('open', () => { this.log.info("Connection opened"); });
        port.on('close', () => {
            this.queue = [];
            this.connectionType = undefined;
            this.port = undefined;
            this.log.info("Connection closed");
            this.connectionListener.emit({ type: ConnectionEventType.DISCONNECTED });
        });
        port.on('error', (err) => {
            this.log.error(err);
            this.queue = [];
            this.connectionType = undefined;
            this.connectionListener.emit({ type: ConnectionEventType.ERROR, error: err });
        });

        port.open((err) => {
            if (err) {
                this.queue = [];
                this.connectionType = undefined;
                this.port = undefined;
                this.log.error(err);
                this.connectionListener.emit({ type: ConnectionEventType.ERROR, error: err });
                resolveCb(false);
            }
            else {
                this.connectionListener.emit({ type: ConnectionEventType.CONNECTED });
                resolveCb(true);
            }
        });

        port.on('data', this.parseSerialRpcData.bind(this));

        const parser = port.pipe(new DelimiterParser({ delimiter: '\n' }))
        parser.on('data', this.parseSerialData.bind(this)); // emits data after every '\n'

        this.connectionType = ConnectionType.serial;
        this.port = port;

        return promise;
    }

    /**
     * Opens a HID device at the given path and wires up data/error/close
     * handlers. On macOS the device is opened in non-exclusive mode.
     */
    private async connectWithHID(portPath: string): Promise<boolean> {
        if (this.connectedDevice) {
            this.log.info("A device is already connected")
            return Promise.reject(new WLDeviceError(WLDeviceErrorCode.AlreadyConnected, "A device is already connected"));
        }

        try {
            let connectingDevice = process.platform === "darwin" ? await HIDAsync.open(portPath, { nonExclusive: true }) : await HIDAsync.open(portPath);

            connectingDevice.on('close', () => {
                this.cleanOnDisconnect();
                this.log.info("Connection closed");

                this.connectionListener.emit({ type: ConnectionEventType.DISCONNECTED });
            });
            connectingDevice.on('error', (err) => {
                this.log.error(err);
                this.cleanOnDisconnect()
                this.connectionListener.emit({ type: ConnectionEventType.ERROR, error: err });
            });
            connectingDevice.on('data', this.parseHIDdata.bind(this));

            this.connectionType = ConnectionType.hid;
            this.connectedDevice = connectingDevice;
            this.connectionListener.emit({ type: ConnectionEventType.CONNECTED });
            return true;
        } catch (error) {
            this.cleanOnDisconnect();
            this.log.error(error);
            this.connectionListener.emit({ type: ConnectionEventType.ERROR, error: error });
            throw error;
        }
    }

    /**
     * Creates a {@link ResolverEntry} that automatically clears `timer` and
     * deletes the entry from `map` when either callback fires. Centralises the cleanup
     * logic shared by every in-flight request.
     */
    private makeResolver(
        map: Map<string, ResolverEntry>,
        key: string,
        resolve: (value: any) => void,
        reject: (reason: any) => void,
        timer: ReturnType<typeof setTimeout>
    ): ResolverEntry {
        const cleanup = () => {
            clearTimeout(timer);
            map.delete(key);
        };
        return {
            resolve: (value) => {
                cleanup();
                resolve(value);
            },
            reject: (err) => {
                cleanup();
                reject(err);
            },
        };
    }

    /**
     * Rejects all in-flight RPC and legacy request promises with a
     * {@link WLDeviceErrorCode.DeviceDisconnected} error so callers don't hang
     * indefinitely after the device goes away.
     */
    private rejectPendingResolvers() {
        const disconnectError = new WLDeviceError(WLDeviceErrorCode.DeviceDisconnected, "Device disconnected");

        for (const value of this._rpcResolver.values()) {
            try {
                value.reject(disconnectError);
            } catch (error) {
                this.log.error("Error while rejecting resolver", error);
            }
        }

        for (const value of this._responseResolvers.values()) {
            try {
                value.reject(disconnectError);
            } catch (error) {
                this.log.error("Error while rejecting resolver", error);
            }
        }
    }

    /**
     * Resets all transport state after a disconnection (intentional or unexpected).
     * Clears the send queue, pending resolvers, accumulated RPC buffer, and both
     * device handles so the instance is safe to reuse with a new {@link connect} call.
     */
    private cleanOnDisconnect() {
        this.rejectPendingResolvers();
        this.queue = [];
        this.connectionType = undefined;
        this.connectedDevice = undefined;
        this.port = undefined;
        this._responseResolvers.clear();
        this._rpcResolver.clear();
        this.rpcResponse = "";
        this.pending = false;
    }

    /** @inheritDoc */
    public cleanCommQueue() {
        this.rejectPendingResolvers();
        this._responseResolvers.clear();
        this._rpcResolver.clear();
        this.rpcResponse = "";
        this.queue = [];
        this.pending = false;
    }

    /** @inheritDoc */
    public async disconnect(): Promise<void> {
        if (this.connectionType === ConnectionType.hid) {
            this.log.info("Disconnecting HID device");
            try {
                await this.connectedDevice?.close();
                this.connectedDevice?.removeAllListeners();
            } catch (error) {
                this.log.error("Failed to disconnect", error);
            }
        } else {
            this.log.info("Disconnecting serial device");
            this.port?.close();
        }
        this.cleanOnDisconnect();
    }

    /** @inheritDoc */
    isConnected(): boolean {
        return (this.connectionType === ConnectionType.hid && !!this.connectedDevice) ||
               (this.connectionType === ConnectionType.serial && !!this.port);
    }

    /** @inheritDoc */
    async sendLegacyRpcRequest(rpc: string, args: string | null = null): Promise<any> {
        return this.enqueue(() => this._sendLegacyRpcRequest(rpc, args))
    }

    private _sendLegacyRpcRequest(rpc: string, args: string | null = null): Promise<any> {
        const message = (!args)
            ? `#${rpc}#\r\n`
            : `#${rpc}#${args}#\r\n`;

        return new Promise<any>((resolve, reject) => {
            const timer = setTimeout(() => {
                this._responseResolvers.get(rpc)?.reject(new WLDeviceError(WLDeviceErrorCode.Timeout, "Request timed out"));
            }, 10000);

            this._responseResolvers.set(rpc, this.makeResolver(this._responseResolvers, rpc, resolve, reject, timer));

            this.sendData(message).catch(err => {
                this._responseResolvers.get(rpc)?.reject(err);
            });
        });
    }

    /** @inheritDoc */
    public sendJsonRpcRequest(request: string, id: string): Promise<any> {
        return this.enqueue(() => this._sendJsonRpcRequest(request, id), id);
    }

    private _sendJsonRpcRequest(request: string, id: string): Promise<any> {
        this.log.debug("Started sending RPC call, id:", id);
        this.rpcResponse = "";

        return new Promise<string>((resolve, reject) => {
            const timer = setTimeout(() => {
                this._rpcResolver.get(id)?.reject(new WLDeviceError(WLDeviceErrorCode.Timeout, "Request timed out"));
            }, 10000);

            this._rpcResolver.set(id, this.makeResolver(this._rpcResolver, id, resolve, reject, timer));

            this.sendData(request).catch(err => {
                this._rpcResolver.get(id)?.reject(err);
            });
        });
    }

    /**
     * Dispatches raw data to the device over the active transport.
     * @param message - The string payload to send.
     * @throws {WLDeviceError} with code `DeviceDisconnected` if no device is connected,
     *         or `WriteFailed` if the transport write failed.
     */
    private async sendData(message: string): Promise<void> {
        if (!this.isConnected()) {
            throw new WLDeviceError(WLDeviceErrorCode.DeviceDisconnected, "cannot send, no device connected");
        }
        if (this.connectionType === ConnectionType.serial) {
            return this.sendDataSerial(message);
        }
        return this.sendDataHID(message);
    }

    /**
     * Writes a string directly to the serial port and drains the buffer.
     * @throws {WLDeviceError} with code `WriteFailed` if the write or drain fails.
     */
    private sendDataSerial(data: string): Promise<void> {
        return new Promise<void>((resolve, reject) => {
            const port = this.port!; // Capture reference — port may be nulled on disconnect before callbacks fire
            port.write(data, (writeError?: Error | null) => {
                if (writeError) {
                    this.log.error("Error sending serial data:", writeError);
                    reject(new WLDeviceError(WLDeviceErrorCode.WriteFailed, writeError.message));
                    return;
                }

                port.drain((drainError?: Error | null) => {
                    if (drainError) {
                        this.log.error("Error draining serial data:", drainError);
                        reject(new WLDeviceError(WLDeviceErrorCode.WriteFailed, drainError.message));
                        return;
                    }

                    resolve();
                });
            });
        });
    }

    /**
     * Frames and sends a string payload over HID. Messages longer than 61 bytes
     * are automatically split into multiple 64-byte HID reports.
     *
     * @throws {WLDeviceError} with code `WriteFailed` if the write fails.
     */
    private async sendDataHID(message: string): Promise<void> {
        const MAX_CHUNK_SIZE = 61;
        const startTime = Date.now();

        try {
            const connectedDevice = this.connectedDevice!; // Capture reference — device may be nulled on disconnect between loop iterations
            // Convert to bytes first — byte length may exceed character length for non-ASCII
            const messageBuffer = Buffer.from(message);
            const messageByteLength = messageBuffer.length;
            let offset = 0;
            let packetNum = 1;

            while (offset < messageByteLength) {
                const chunkSize = Math.min(MAX_CHUNK_SIZE, messageByteLength - offset);
                this.log.debug("Sending packet:", packetNum, "size:", chunkSize, "offset:", offset);

                const data = Buffer.alloc(64); // Standard HID report size
                data[0] = 0x06; // HID byte
                data[1] = this.CHANNEL_RPC;
                data[2] = chunkSize;
                messageBuffer.copy(data, 3, offset, offset + chunkSize);

                await connectedDevice.write(data);

                offset += chunkSize;
                packetNum++;
            }

            const elapsedTime = (Date.now() - startTime) / 1000;
            this.log.debug("Send complete, packets:", packetNum - 1, "bytes:", messageByteLength, "seconds:", elapsedTime.toFixed(3));
        } catch (error: any) {
            this.log.error("Error sending message:", error);
            throw new WLDeviceError(WLDeviceErrorCode.WriteFailed, error.message);
        }
    }

    /**
     * Processes an incoming HID report, demultiplexes by channel (debug vs RPC),
     * and forwards complete newline-terminated lines to the appropriate parser.
     */
    private parseHIDdata(data: any) {
        // Process according to protocol
        try {
            const packet = this.parseHIDReport(data);
            const channel = packet.channel;
            const textData = packet.payload;

            // Add data to the appropriate buffer
            if (this.buffers[channel] === undefined) {
                this.buffers[channel] = '';
            }

            // Look for line endings in the received data
            this.buffers[channel] += textData;
            const lines = this.buffers[channel].split(/\r?\n/);

            // We only get here if we have a complete message or we have more than one message
            if (lines.length > 1 || textData.endsWith('\n') || textData.endsWith('\r')) {
                // All complete lines should be printed
                for (let i = 0; i < lines.length - 1; i++) {
                    const line = lines[i].trim();
                    if (line) {
                        const prefix = channel === this.CHANNEL_DEBUG ? '[LOG]' : '[RPC]';
                        if (channel === this.CHANNEL_RPC) {
                            this.log.debug(prefix, line);
                            try {
                                this.parseRpcData(line);
                            } catch (error: any) {
                                this.log.error("Failed to parse RPC data:", error.message);
                            }
                        } else {
                            this.log.info(prefix, line);
                        }
                    }
                }
                // We keep the incomplete line, if all are completed we have empty string here
                this.buffers[channel] = lines[lines.length - 1];
            }
        } catch (error: any) {
            this.log.error("Failed to parse packet:", error.message);
            this.buffers[this.CHANNEL_DEBUG] = "";
            this.buffers[this.CHANNEL_RPC] = "";
        }
    }

    /**
     * Extracts channel, length, and UTF-8 payload from a raw 64-byte HID report.
     */
    private parseHIDReport(data: any) {
        // Skip first byte (HID stuff)
        const channel = data[1];
        const length = data[2];
        const payload = data.slice(3, 3 + length);

        return {
            channel,
            length,
            payload: Buffer.from(payload).toString('utf8')
        };
    }

    /** Decodes a serial data buffer and routes it to the legacy response parser. */
    private parseSerialData(data: Uint8Array) {
        const decoded = new TextDecoder().decode(data);
        this.parseData(decoded);
    }

    /**
     * Parses legacy `#rpc#response#` formatted data received over serial and
     * resolves the matching pending request promise.
     */
    private parseData(data: string): void {
        let str = data.replace(/[\r\n]+$/, "");

        try {
            if (this.checkMessage(str, "version")) {
                let version = this.extractResponse(str);
                this._responseResolvers.get("version")?.resolve(version);
            } else if (this.checkMessage(str, "dfu")) {
                let response = this.extractResponse(str);
                this._responseResolvers.get("dfu")?.resolve(response === "ok");
            } else if (this.checkMessage(str, "selftest")) {
                let response = this.extractResponse(str);
                this._responseResolvers.get("selftest")?.resolve(response === "ok");
            } else if (this.checkMessage(str, "bootloader")) {
                let response = this.extractResponse(str);
                this._responseResolvers.get("bootloader")?.resolve(response === "ok");
            }
        } catch (error) {
            this.log.error(error);
        }
    }

    /** Decodes a serial data buffer and routes it to the JSON-RPC response parser. */
    private parseSerialRpcData(data: Uint8Array) {
        const string = new TextDecoder().decode(data);
        this.parseRpcData(string);
    }

    /**
     * Accumulates incoming JSON fragments and, once a complete JSON object is
     * received, either resolves a pending RPC promise or dispatches a device
     * notification via {@link handleNotifyMessage}.
     *
     * @returns `true` if the data was consumed or ignored; `false` if more data is needed.
     */
    private parseRpcData(data: string): boolean {
        // If we have no accumulated response, check if this chunk contains a JSON start
        if (this.rpcResponse.length === 0) {
            const jsonStart = data.indexOf('{');
            if (jsonStart === -1) {
                return true; // No JSON start found, ignore this chunk
            }
            // Only add from the first opening brace
            this.rpcResponse = data.slice(jsonStart);
        } else {
            // We're already accumulating JSON, append the entire chunk
            this.rpcResponse += data;
        }

        try {
            const parsedData = JSON.parse(this.rpcResponse);
            let id = parsedData.id ?? parsedData.i;
            if (id !== undefined && typeof id === "number") {
                id = String(id);
            }
            const method = parsedData.method ?? parsedData.m;
            // All messages should at have either id or method
            if (!id && !method) {
                this.log.warn("Received RPC call without id and method");
                this.rpcResponse = "";
                return false;
            }

            if (!id && method) {
                this.handleNotifyMessage(parsedData);
                this.rpcResponse = "";
            } else {
                const resolverEntry = this._rpcResolver.get(id);
                if (resolverEntry) {
                    resolverEntry.resolve(this.rpcResponse);
                    this.rpcResponse = "";
                } else {
                    this.log.warn("No resolver found for id:", id, "response:", this.rpcResponse);
                    this.rpcResponse = "";
                }
            }
        } catch (error) {
            // log.error(error);
            // If parsing fails, we need more data
            return false;
        }
        return true;
    }

    /** @inheritDoc */
    public addNotifyHandler(method: string, handler: (params: any) => any) {
        this.log.info("Added notify handler for method:", method);
        this._notifyResolvers.set(method, handler);
    }

    /** @inheritDoc */
    public removeNotifyHandler(method: string) {
        this.log.info("Removed notify handler for method:", method);
        this._notifyResolvers.delete(method);
    }

    /**
     * Tests whether `msg` matches the legacy response pattern `#rpc#...#`.
     */
    private checkMessage(msg: string, rpc: string): boolean {
        let re = new RegExp(String.raw`\#${rpc}#.*#$`, "g");
        return msg.search(re) !== -1;
    }

    /**
     * Extracts the payload between the second and third `#` delimiters in a
     * legacy `#rpc#payload#` response string.
     */
    private extractResponse(msg: string): string {
        let re = new RegExp(String.raw`\#.*?\#(.*?)\#$`, "g");
        let match = re.exec(msg);
        if (match && match[1]) {
            return match[1];
        }
        return "";
    }

    /**
     * Dispatches a device-initiated notification to the registered handler
     * for its `method` (or compact `m`) field.
     */
    private handleNotifyMessage(notifyMessage: any): boolean {
        const method = notifyMessage.method || notifyMessage.m;
        const handler = this._notifyResolvers.get(method);
        if (!handler) {
            this.log.debug("Cannot find notify handler for method:", method);
            return false;
        }
        handler(notifyMessage.params || notifyMessage.p);
        return true;
    }

    /**
     * Adds an async task to the sequential send queue. Tasks execute one at a
     * time with a 50 ms cooldown between each to avoid overwhelming the device.
     *
     * @param fn - The async function to execute when this task reaches the front.
     * @param id - Optional identifier used by {@link abortJsonRpcRequest} to remove the task before execution.
     * @returns A promise that resolves/rejects with the result of `fn`.
     */
    private enqueue<T>(fn: () => Promise<T>, id?: string): Promise<T> {
        return new Promise<T>((resolve, reject) => {
            // Add the task to the queue
            this.queue.push({ id, fn, resolve, reject });
            this.log.info("Added call to queue, new queue length:", this.queue.length);
            // Kick off processing if not already running
            this.process();
        });
    }

    /** @inheritDoc */
    async abortJsonRpcRequest(id: string) {
        this.queue = this.queue.filter((task) => task.id !== id);
        const message = `{"error":{"message": "task aborted"}}`;
        this._rpcResolver.get(id)?.resolve(message);
    }

    /**
     * Drains the send queue one task at a time.
     *
     * Picks the next {@link Task} off the front of the queue, runs it, then
     * waits 50 ms before processing the following task. The 50 ms cooldown
     * gives device firmware enough time to process each command before the
     * next one arrives. Re-entrant calls return immediately — only one task
     * runs at a time, guarded by {@link pending}.
     */
    private async process() {
        // If a task is already running, do nothing
        if (this.pending) {
            this.log.debug("Task already in progress, waiting for it to finish");
            return;
        }

        this.pending = true;
        const task = this.queue.shift();
        if (!task) {
            this.log.debug("No more tasks to process");
            this.pending = false;
            return;
        }

        try {
            this.log.debug("Processing next task");
            const result = await task.fn();
            task.resolve(result);
        } catch (err) {
            this.log.debug("Task failed");
            task.reject(err);
        } finally {
            // We need a small delay between calls so that the device has time to handle the request
            await new Promise((r) => setTimeout(r, 50));
            this.pending = false;
            // Process next task in the queue
            this.process();
        }
    }
}

/** Internal queue entry used by {@link WLDeviceCommImpl} to serialize outgoing requests. */
type Task<T> = {
    /** Optional identifier for cancellation via {@link WLDeviceCommImpl.abortJsonRpcRequest}. */
    id?: string;
    /** The async work to perform when this task is dequeued. */
    fn: () => Promise<T>;
    /** Resolves the outer promise returned by {@link WLDeviceCommImpl.enqueue}. */
    resolve: (value: T) => void;
    /** Rejects the outer promise returned by {@link WLDeviceCommImpl.enqueue}. */
    reject: (reason: any) => void;
};

/** Stores both resolve and reject callbacks for an in-flight request promise. */
type ResolverEntry = {
    resolve: (value: any) => void;
    reject: (reason: any) => void;
};

type NotifyHandler = (params: any) => any;

export default WLDeviceCommImpl;