import { DeviceLayoutType } from "../../common/types/device_layout_type";
import { DeviceType } from "../../common/types/device_type";
import { DeviceDefinition } from "../types/device_definition";

/**
 * Master lookup table that maps USB Product IDs (PIDs) to their
 * {@link DeviceDefinition} (device type + layout variant).
 *
 * When a HID device is enumerated, its `productId` is looked up here
 * to determine which Work Louder product it is and which layout it uses.
 */
export const DEVICE_REGISTRY = new Map<number, DeviceDefinition>([
    // Nomad
    [0x1001, { type: DeviceType.NomadE, layout: DeviceLayoutType.unknown }],//LEGACY
    [0x8294, { type: DeviceType.NomadE, layout: DeviceLayoutType.ansi }],
    [0x8295, { type: DeviceType.NomadE, layout: DeviceLayoutType.iso }],
    [0x8370, { type: DeviceType.NomadEV2, layout: DeviceLayoutType.iso }],
    [0x8371, { type: DeviceType.NomadEV2, layout: DeviceLayoutType.ansi }],

    // Knob
    [0x8296, { type: DeviceType.Knob, layout: DeviceLayoutType.ansi }],
    [0x82E3, { type: DeviceType.Knob, layout: DeviceLayoutType.iso }],

    // Knob F1
    [0x8396, { type: DeviceType.KnobF1, layout: DeviceLayoutType.ansi }],
    [0x8397, { type: DeviceType.KnobF1, layout: DeviceLayoutType.iso }],

    // Micro V2
    [0x8297, { type: DeviceType.CreatorMicroV2, layout: DeviceLayoutType.universal }],
    [0x8298, { type: DeviceType.CreatorMicroV2, layout: DeviceLayoutType.universal }],
    [0x8360, { type: DeviceType.CodexMicro, layout: DeviceLayoutType.universal }],

    // XYZ
    [0x8346, { type: DeviceType.XYZ, layout: DeviceLayoutType.ansi }],
]);
