import { basename, dirname, join } from 'node:path';
import type { WasmLvglModule } from './wasm_types';

let wasmModule: WasmLvglModule | null = null;

function getWasmModulePath(): string {
    // Vitest executes this source file directly, while consumers execute the
    // bundled dist/index.js. Select the layout explicitly so a load failure in
    // the published package is not hidden by an unrelated fallback error.
    const isSourceLayout =
        basename(__dirname) === 'wl_lvgl'
        && basename(dirname(__dirname)) === 'src';

    return isSourceLayout
        ? join(__dirname, '..', '..', 'wasm-node', 'wl_lvgl_wasm')
        : join(__dirname, '..', 'wasm-node', 'wl_lvgl_wasm');
}

function getWasm(): WasmLvglModule {
    if (!wasmModule) {
        const mod: WasmLvglModule = require(getWasmModulePath());
        mod.wasm_start();
        wasmModule = mod;
    }
    return wasmModule;
}

/**
 * Convert an image to LVGL v9 binary format (I8 color).
 *
 * The input format is auto-detected by the underlying `icu_lib` encoder via the
 * Rust `image` crate. Supported formats include PNG, JPEG, BMP, GIF, TIFF,
 * WebP, ICO, TGA, PBM, PGM, PPM, and PAM.
 *
 * WASM is loaded lazily on the first call.
 */
export function convertImageToLvgl(data: Uint8Array): Uint8Array {
    return getWasm().convert_image_to_lvgl_format(new Uint8Array(data));
}

/**
 * Convert an LVGL binary image back to PNG.
 *
 * WASM is loaded lazily on the first call.
 */
export function convertLvglToImage(data: Uint8Array): Uint8Array {
    return getWasm().convert_lvgl_format_to_image(new Uint8Array(data));
}
