/**
 * Encodes a string into its UTF-8 byte representation and escapes every
 * non-printable-ASCII byte as `\xHH`. Printable ASCII characters
 * (0x20–0x7E) are kept as-is.
 *
 * @param str - The input string to escape.
 * @returns The escaped string with non-ASCII bytes represented as `\xHH` sequences.
 */
export function escapeUTF8(str: string) {
    const encoder = new TextEncoder();
    const bytes = encoder.encode(str);

    let out = '';
    for (let b of bytes) {
        if (b >= 0x20 && b <= 0x7E) {
            out += String.fromCharCode(b);
        } else {
            out += '\\x' + b.toString(16).padStart(2, '0');
        }
    }
    return out;
}

/**
 * Replaces every non-ASCII character in a string with `\uHHHH` escape
 * sequences. Characters outside the Basic Multilingual Plane (code points
 * above U+FFFF) are encoded as surrogate pairs (`\uHHHH\uHHHH`).
 *
 * Used internally by {@link WLRPCClient} to safely serialize JSON-RPC
 * payloads before transmitting them over HID/serial.
 *
 * @param str - The input string to escape.
 * @returns The string with all non-ASCII characters replaced by `\u` escapes.
 */
export function escapeUnicode(str: string) {
    return str.replace(/[^\x00-\x7F]/gu, (char) => {
        const codePoint = char.codePointAt(0);
        if (codePoint === undefined) {
            // `char` comes from a regex match, so this should never happen.
            throw new Error("Unexpected undefined codePoint");
        }
        if (codePoint > 0xFFFF) {
            const highSurrogate = (codePoint - 0x10000) >> 10 | 0xD800;
            const lowSurrogate = (codePoint - 0x10000) & 0x3FF | 0xDC00;
            return `\\u${highSurrogate.toString(16).padStart(4, '0')}\\u${lowSurrogate.toString(16).padStart(4, '0')}`;
        }
        return `\\u${codePoint.toString(16).padStart(4, '0')}`;
    });
}