/**
 * Represents a single downloadable asset attached to a GitHub release.
 */
export class GithubAsset {
    /** File name of the asset (e.g. `firmware.bin`). */
    name: string;
    /** Direct download URL for the asset binary. */
    downloadUrl: string;

    constructor(name: string, downloadUrl: string) {
        this.name = name;
        this.downloadUrl = downloadUrl;
    }

    /**
     * Creates a {@link GithubAsset} from a raw GitHub API JSON object.
     *
     * @param json - A single entry from the `assets` array of a GitHub release.
     * @returns The parsed asset, or `undefined` when required fields are missing.
     */
    static fromJson(json: any): GithubAsset | undefined {
        if (!json.name || !json.browser_download_url) {
            return undefined;
        }
        return new GithubAsset(json.name, json.browser_download_url);
    }
}
