import semver from "semver";
import { platform } from "node:os";
import { RepositoryType } from "./types/repository_type";
import { DeviceType } from "../common/types/device_type";
import { Logger, noopLogger } from "../browser_safe";
import { prefixLogger } from "../utils/logger_utils";
import { ReleaseInfo } from "./types/release_info";
import { GithubAsset } from "./types/github_asset";
import { GithubData } from "./types/github_data";

const githubOwner = "worklouder";

/**
 * Checks for firmware and application updates by querying the GitHub Releases
 * API for Work Louder repositories.
 *
 * Supports ETag-based conditional requests to minimise GitHub API usage and
 * provides an in-memory cache with a 60-second TTL.
 *
 * @example
 * ```ts
 * const release = new WLRelease(logger);
 * const latest = await release.getLatestRelease(RepositoryType.NomadFirmware);
 * ```
 */
export default class WLRelease {
    private log: Logger;
    private dataCache: Map<string, string> = new Map();

    /**
     * @param logger - Optional {@link Logger} instance. Defaults to a silent
     *                 no-op logger when omitted.
     */
    constructor(logger?: Logger) {
        this.log = prefixLogger(logger ?? noopLogger, "wl_release");
    }

    /**
     * Fetches the latest release from a Work Louder GitHub repository.
     *
     * When {@link betaVersion} is `false` (the default) pre-release versions
     * are excluded from the result set.
     *
     * @param repository  - The GitHub repository to query.
     * @param betaVersion - When `true`, pre-release versions are included.
     * @returns The latest {@link ReleaseInfo}, or `undefined` when no
     *          matching release is found.
     */
    public async getLatestRelease(
        repository: RepositoryType,
        betaVersion: boolean = false,
    ): Promise<ReleaseInfo | undefined> {
        try {
            const url = `https://api.github.com/repos/${githubOwner}/${repository}/releases`;
            const data: any = await this.fetchFromGithub(url);

            if (!Array.isArray(data) || data.length < 1) {
                this.log.error("No releases found");
                return undefined;
            }

            let releases: GithubData[] = [];
            for (const entry of data) {
                try {
                    releases.push(GithubData.fromJson(entry));
                } catch {
                    // Skip malformed release entries
                }
            }

            if (!betaVersion) {
                releases = releases.filter((element: any) => !element.name.includes("rc"));
            }

            if (releases.length === 0) {
                this.log.error("No valid releases found after filtering");
                return undefined;
            }

            const latestRepo = releases[0];
            const githubLatestVersion = latestRepo.tagName;
            const changeLog = latestRepo.body;

            const versionAssets = this.getAssetFromData(latestRepo, repository);
            if (!versionAssets) {
                this.log.error("No asset found in the latest release");
                return undefined;
            }

            const release: ReleaseInfo = {
                version: githubLatestVersion,
                fetchedAt: Date.now(),
                changeLog: changeLog,
                downloadUrl: versionAssets.downloadUrl,
            };
            return release;
        } catch (error) {
            this.log.error("Cannot get", repository, "GitHub latest release, error:", error);
            return undefined;
        }
    }

    /**
     * Extracts the relevant downloadable asset from a GitHub release.
     *
     * For {@link RepositoryType.InputApp} the asset is platform-specific
     * (`.exe` on Windows, `.dmg` on macOS). For firmware repositories the
     * first `.bin` asset is returned.
     *
     * @param githubData - Parsed release data containing the asset list.
     * @param type       - The repository type, used to select the correct asset.
     * @returns The matching {@link GithubAsset}, or `undefined` when no
     *          suitable asset exists.
     */
    private getAssetFromData(githubData: GithubData, type: RepositoryType): GithubAsset | undefined {
        if (type === RepositoryType.InputApp) {
            const os = platform();
            return githubData.assets.find((asset) => {
                if (os === "win32" && asset.name.endsWith(".exe")) {
                    return true;
                } else if (os === "darwin" && asset.name.endsWith(".dmg")) {
                    return true;
                }
                return false;
            });
        }
        return githubData.assets.find((asset) => asset.name.endsWith(".bin"));
    }

    /**
     * Fetches JSON from the GitHub API with ETag-based caching.
     *
     * Cached responses are reused for up to 60 seconds. After that the
     * request is re-issued with an `If-None-Match` header so GitHub can
     * return a `304 Not Modified` when nothing has changed.
     *
     * @param url - Fully-qualified GitHub API URL.
     * @returns The parsed JSON response body.
     * @throws When the network request fails or the response status is >= 400.
     */
    private async fetchFromGithub(url: string): Promise<any> {
        const cacheKey = url;
        const headers: Record<string, string> = {
            "Accept": "application/json",
        };

        const cached = this.getDataFromCache(cacheKey);

        if (cached && cached.ts && cached.etag && cached.data) {
            this.log.info("Using cached result");
            if (Date.now() < cached.ts + 60000) {
                return cached.data;
            }
            headers["If-None-Match"] = cached.etag;
        }

        const response = await this.fetchDataWithTimeout(url, headers);
        if (response.status === 304) {
            if (cached && cached.data) {
                cached.ts = Date.now();
                this.dataCache.set(cacheKey, JSON.stringify(cached));
                return cached.data;
            }
            this.log.error("Something went wrong during cache retrieval");
            this.dataCache.delete(cacheKey);
            return this.fetchFromGithub(url);
        }
        const etag = response.headers.get("etag");
        const data: any = await response.json();
        this.dataCache.set(cacheKey, JSON.stringify({
            etag,
            ts: Date.now(),
            data
        }));
        return data;
    }

    /**
     * Issues a `fetch` with a 10-second abort timeout.
     *
     * @param url     - The URL to fetch.
     * @param headers - Optional request headers.
     * @returns The raw {@link Response} object.
     * @throws When the request times out, is aborted, or returns a 4xx/5xx status.
     */
    private async fetchDataWithTimeout(url: string, headers?: Record<string, string>): Promise<Response> {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort("api call took too long"), 10000);
        try {
            const response = await fetch(
                url,
                {
                    headers: headers,
                    signal: controller.signal
                }
            );
            clearTimeout(timeout);

            if (response.status >= 400) {
                const message = `failed to fetch data with code: ${response.status}`;
                this.log.error(message);
                throw new Error(message);
            }
            return response;
        } catch (error) {
            clearTimeout(timeout);
            throw error;
        }
    }

    /**
     * Retrieves and deserialises a previously cached response.
     *
     * If the cached JSON is malformed the entry is evicted automatically.
     *
     * @param key - Cache key (typically the request URL).
     * @returns The parsed cache entry, or `undefined` when no valid entry exists.
     */
    private getDataFromCache(key: string): any {
        const jsonData = this.dataCache.get(key);
        if (!jsonData) {
            return undefined;
        }
        try {
            return JSON.parse(jsonData);
        } catch {
            this.dataCache.delete(key);
            return undefined;
        }
    }

    /**
     * Compares two semver strings and returns whether `remoteVersion` is
     * strictly greater than `localVersion`.
     *
     * @param remoteVersion - The version to test.
     * @param localVersion  - The baseline version.
     * @returns `true` when the remote is newer, `false` when it is not,
     *          or `undefined` when either string is not valid semver.
     */
    public isVersionNewer(
        remoteVersion: string,
        localVersion: string
    ): boolean | undefined {
        try {
            return semver.gt(remoteVersion, localVersion);
        } catch (e) {
            return undefined;
        }
    }

    /**
     * Returns `true` when the given version string contains a semver
     * pre-release tag (e.g. `1.0.0-beta.1`).
     *
     * @param appVersion - The version string to inspect.
     */
    public isBeta(appVersion: string): boolean {
        return semver.prerelease(appVersion) !== null;
    }

    /**
     * Determines whether the device firmware should be updated based on the
     * current application version and device type.
     *
     * Beta users are always checked against pre-release firmware. Stable
     * users are only checked when they are already running the latest
     * application version.
     *
     * @param appVersion      - The currently running application version.
     * @param firmwareVersion - The firmware version string reported by the device.
     * @param deviceType      - The connected device type.
     * @returns The {@link ReleaseInfo} for the available update, or
     *          `undefined` when no update is needed.
     */
    public async shouldUpdateFirmware(appVersion: string, firmwareVersion: string, deviceType: DeviceType): Promise<ReleaseInfo | undefined> {
        if (!appVersion) {
            this.log.error("Cannot get app version");
            return undefined;
        }

        if (this.isBeta(appVersion)) {
            return this.hasFirmwareUpdate(firmwareVersion, true, deviceType);
        }

        const latestAppVersion = await this.getLatestRelease(RepositoryType.InputApp);
        if (!latestAppVersion) {
            this.log.error("Cannot get latest app release");
            return undefined;
        }

        this.log.info("Latest app version:", latestAppVersion.version);
        const isInputVersionMoreRecent = this.isVersionNewer(latestAppVersion.version, appVersion);

        if (isInputVersionMoreRecent === undefined || isInputVersionMoreRecent) {
            this.log.info("Input is not at the latest version, firmware cannot be updated");
            return undefined;
        }
        return this.hasFirmwareUpdate(firmwareVersion, false, deviceType);
    }

    /**
     * Detects non-release (development) firmware versions.
     *
     * Development versions include dirty builds, commit-hash suffixed
     * versions, and other non-standard semver formats commonly produced
     * during firmware development.
     *
     * @param version - The firmware version string to inspect.
     * @param device  - Optional device type for edge-case handling.
     * @returns `true` when the version appears to be a development build.
     */
    public isDevVersion(version: string, device?: DeviceType): boolean {
        if (this.isDirtyMicro(version, device)) {
            this.log.debug("Fw is creator micro v2 0.2.1-dirty — not a dev version");
            return false;
        }
        if (/^\d+\.\d+\.\d+$/.test(version)) {
            return false;
        } else if (/^\d+\.\d+\.\d+-rc.\d+$/.test(version)) {
            return false;
        } else if (/^\d+\.\d+\.\d+-rc.\d+-dirty$/.test(version)) {
            return true;
        }

        return /^\d+\.\d+\.\d+(?:(?:-\d+-g[0-9a-f]{7})|(?:-g[0-9a-f]{7})|(?:-dirty))?(?:-dirty)?$/.test(version);
    }

    /**
     * Checks whether a firmware update is available for the given device.
     *
     * Skips the update when the device is running a development build or
     * when switching from a pre-release to a stable firmware track while
     * the user is on a beta application version.
     *
     * @param firmwareVersion - The firmware version string reported by the device.
     * @param isBeta       - Whether pre-release firmware should be considered.
     * @param deviceType   - The connected device type.
     * @returns The {@link ReleaseInfo} for the available update, or
     *          `undefined` when no update is needed.
     */
    public async hasFirmwareUpdate(firmwareVersion: string, isBeta: boolean = false, deviceType: DeviceType): Promise<ReleaseInfo | undefined> {
        const firmwareRepository = WLRelease.getFirmwareRepo(deviceType);
        if (firmwareRepository === RepositoryType.Unknown) {
            return undefined;
        }

        const latestFirmwareRelease = await this.getLatestRelease(firmwareRepository, isBeta);
        if (!latestFirmwareRelease) {
            this.log.error("Cannot get latest firmware release");
            return undefined;
        }

        // When on a beta app, do not downgrade from a pre-release firmware to stable.
        // The app should auto-update from pre-release to stable, keeping the
        // developer experience smooth while avoiding unexpected firmware changes.
        if (isBeta && semver.prerelease(latestFirmwareRelease.version) === null && semver.prerelease(firmwareVersion) !== null && !this.isDirtyMicro(firmwareVersion, deviceType)) {
            return undefined;
        }

        try {
            if (this.isDevVersion(firmwareVersion, deviceType)) {
                this.log.info("Device is on a dev version, skipping update");
            } else if (this.isVersionNewer(latestFirmwareRelease.version, firmwareVersion) === true) {
                this.log.info("Firmware update available: version", firmwareVersion, "is outdated");
                return latestFirmwareRelease;
            }
        } catch (error) {
            this.log.error("Could not get firmware info, cannot update");
            return undefined;
        }

        this.log.info("No firmware update needed");
        return undefined;
    }

    /**
     * Edge-case check for the Creator Micro V2 `0.2.1-dirty` build which
     * is a known stable release despite containing a dirty suffix.
     */
    private isDirtyMicro(version: string, deviceType?: DeviceType): boolean {
        return deviceType === DeviceType.CreatorMicroV2 && version === "0.2.1-dirty";
    }

    /**
     * Maps a {@link DeviceType} to its corresponding firmware
     * {@link RepositoryType}.
     *
     * @param deviceType - The device type to look up.
     * @returns The matching repository, or {@link RepositoryType.Unknown}
     *          when no firmware repository is configured for the device.
     */
    static getFirmwareRepo(deviceType: DeviceType): RepositoryType {
        switch (deviceType) {
            case DeviceType.NomadE:
                return RepositoryType.NomadFirmware;
            case DeviceType.NomadEV2:
                return RepositoryType.NomadV2Firmware;
            case DeviceType.Knob:
                return RepositoryType.KnobFirmware;
            case DeviceType.KnobF1:
                return RepositoryType.KnobFirmware;
            case DeviceType.CreatorMicroV2:
            case DeviceType.CodexMicro:
                return RepositoryType.CMicroV2Firmware;
            case DeviceType.XYZ:
                return RepositoryType.XyzR2Firmware;
            default:
                return RepositoryType.Unknown;
        }
    }
}
